package client

import (
	"context"

	"github.com/cloudwego/kitex/pkg/utils"
)

// TailHook is a function called after the response is received but before returning to caller.
// Useful for post-response processing like metrics, logging, or cleanup.
type TailHook func(ctx context.Context, req, resp interface{}, err error) error

// WithTailHook adds a post-response hook for unary RPC calls.
// The hook is executed after the response is received, allowing additional processing
// before the result is returned to the caller.
func WithTailHook(hook TailHook) Option {
	return Option{
		F: func(o *Options, di *utils.Slice) {
			if o.TailHooks == nil {
				o.TailHooks = make([]TailHook, 0, 1)
			}
			o.TailHooks = append(o.TailHooks, hook)
		},
	}
}

// TailOption is a functional option that executes after the main RPC completes.
// It can be used for post-processing, metrics collection, or resource cleanup.
type TailOption func(ctx context.Context, req, resp interface{}, err error)

// WithTailOption adds a tail option for unary RPCs.
// Unlike middleware, tail options only run after the RPC completes, and cannot modify the response.
func WithTailOption(fn TailOption) Option {
	return WithTailHook(func(ctx context.Context, req, resp interface{}, err error) error {
		fn(ctx, req, resp, err)
		return nil
	})
}

